  max-width: 580px;
  width: 90%;
  position: relative;
  z-index: 5;
  margin-top: 25px;
}

.ct-012e9b2f .modal--email .column {
}

.ct-012e9b2f .modal--email h2 {
    font-family: "Brandon Grotesque W01 Bold", sans-serif;
    color: #000;
    font-size: 24px;
    line-height: 27px;
    letter-spacing: 1.2px;
    margin-bottom: 15px;
}

.ct-012e9b2f .modal--email figure {
  margin: 0;
  width: 100%;
  height: fit-content;
  position: relative;
  justify-self: end;
}

.ct-012e9b2f .modal--email figure img {
  max-width: 100%;
  width: 100%;
  height: auto;
}

.ct-012e9b2f .modal--email figcaption {
  position: absolute;
  bottom: 30px;
  right: 0;
  text-align: center;
  color: #fff;
  padding: 8px 5px;
  font-style: italic;
  font-family: "Brandon Grotesque W01 Bold", sans-serif;
  font-size: 14px;
}

.ct-012e9b2f .modal--email .form-wrapper {
  display: flex;
  align-items: center;
  justify-content: center;
  transform: translateY(-25px);
  width: 85%;
  margin: 0 auto;
}

.ct-012e9b2f .modal--email .form-wrapper .container {
  width: 100%;
  background-color: #fff;
  border: 20px solid #fff;
  padding: 0;
  position: relative;
}

.ct-012e9b2f .modal--email .form-wrapper--links .extra-padding {
  padding: 10px;
}

.ct-012e9b2f .modal--email .form-wrapper--links {
  color: #b4b4b4;
}

.ct-012e9b2f .modal--email .form-wrapper--links a{
  text-decoration: none;
  color: #b4b4b4;
  text-transform: uppercase;
  font-family: "Brandon Grotesque W01 Bold", sans-serif;
  font-size: 13px;
  padding: 8px 5px 5px;
  display: inline-block;
}

.ct-012e9b2f .modal--email .form-wrapper--links a:hover {
  text-decoration: underline;
}

.ct-012e9b2f .modal--email .form-wrapper form {
  display: inline-block;
  width: 100%;
  display: grid;
  position: relative;
  row-gap: 20px;
}

.ct-012e9b2f .modal--email .form-wrapper input {
  background-color: transparent;
  border: none;
  padding: 10px 15px;
  color: #4d4d4d;
  font-family: "Brandon Grotesque W01 Regular", sans-serif;
  box-shadow: none;
}

.ct-012e9b2f .modal--email .form-wrapper input:focus-visible {
  outline: none;
}

.ct-012e9b2f .modal--email .form-wrapper input:not(input[type=submit]) {
  border-left: transparent 1px solid;
  border-top: transparent;
  border-right: transparent;
  border-bottom: gray 2px solid;
  border-radius: 0px;
  font-family: "Brandon Grotesque W01 Regular",sans-serif;
  font-style: italic;
  font-size: 20px;
  padding: 10px;
}

.ct-012e9b2f .modal--email .form-wrapper label {
  color: #4d4d4d;
  font-family: "Brandon Grotesque W01 Regular",sans-serif;
  font-size: 16px;
  margin: 0;
}

.ct-012e9b2f .modal--email .form-wrapper input[type=checkbox] {
  margin: 0 10px 0 0 !important;
}

.ct-012e9b2f .modal--email .form-wrapper .two-column {
  display: flex;
  column-gap: 20px;
}

.ct-012e9b2f .modal--email .form-wrapper .two-column input {
  width: 50%;
}

.ct-012e9b2f .modal--email .form-wrapper input:not(input[type=submit]):focus {
    color: #495057;
    background-color: #fff;
    border-color: #80bdff;
    outline: 0;
    box-shadow: 0 0 0 0.2rem rgba(0,123,255,0.25);
}

.ct-012e9b2f .modal--email .form-wrapper input[type=submit] {
    width: 100%;
    height: 42px;
    border: #7d3269 2px solid;
    color: #7d3269;
    background: transparent;
    font-size: 18px;
    padding: 0 10px;
    font-family: "Brandon Grotesque W01 Bold",sans-serif;
}

.ct-012e9b2f .modal--email .form-wrapper input[type=submit]:hover {
    color: #fff;
    background-color: #7D3269;
    cursor: pointer;
}

